def corregir_conceptos_facturas_basora(apps, schema_editor):
    Portafolio = apps.get_model('gestion_propiedades', 'Portafolio')
    Factura = apps.get_model('gestion_propiedades', 'Factura')

    portafolios = Portafolio.objects.filter(
        Q(propietario__username__iexact='lbasora@basoraarriaga.com') |
        Q(propietario__email__iexact='lbasora@basoraarriaga.com') |
        Q(nombre__icontains='Basora')
    )

    portafolios.update(formato_concepto_factura='RANGO_FECHAS')

    facturas = Factura.objects.filter(
        contrato__propiedad__portafolio__in=portafolios
    ).exclude(concepto__icontains='migrado')

    nombres_meses = {
        1: 'ENERO', 2: 'FEBRERO', 3: 'MARZO', 4: 'ABRIL', 5: 'MAYO', 6: 'JUNIO',
        7: 'JULIO', 8: 'AGOSTO', 9: 'SEPTIEMBRE', 10: 'OCTUBRE', 11: 'NOVIEMBRE', 12: 'DICIEMBRE'
    }

    actualizadas = 0
    for f in facturas:
        # La fecha de vencimiento/emisión de la factura es el corte final del período (cobro a mes vencido)
        fecha_base = f.fecha_vencimiento or f.fecha_emision or date.today()
        mes_fin = fecha_base.month
        anio_fin = fecha_base.year

        dia = getattr(f.contrato, 'dia_de_pago', 1) or 1
        max_d_fin = calendar.monthrange(anio_fin, mes_fin)[1]
        dia_fin = min(dia, max_d_fin)

        # El período inició un mes antes
        if mes_fin == 1:
            mes_inicio = 12
            anio_inicio = anio_fin - 1
        else:
            mes_inicio = mes_fin - 1
            anio_inicio = anio_fin

        max_d_inicio = calendar.monthrange(anio_inicio, mes_inicio)[1]
        dia_inicio = min(dia, max_d_inicio)

        mes1_str = nombres_meses.get(mes_inicio, '')
        mes2_str = nombres_meses.get(mes_fin, '')

        nuevo_concepto = f"PAGO DESDE EL {dia_inicio} DE {mes1_str} DEL {anio_inicio} HASTA EL {dia_fin} DE {mes2_str} DEL {anio_fin}"
        if f.concepto and '(anticipada)' in f.concepto.lower():
            nuevo_concepto += " (Anticipada)"

        if nuevo_concepto != f.concepto:
            f.concepto = nuevo_concepto
            f.save()
            actualizadas += 1

    print(f"\n[Migración 0045] Facturas de Basora corregidas a período vencido (mes anterior a fecha corte): {actualizadas}")


